def fact(n: int) -> int:
    """Return n! for n >= 0, computed as the product 1 * 2 * ... * n with fact(0) == 1."""
    if n < 0:
        raise ValueError("fact() requires n >= 0")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result


def test_fact_zero() -> None:
    assert fact(0) == 1


def test_fact_one() -> None:
    assert fact(1) == 1


def test_fact_small() -> None:
    assert fact(5) == 120


def test_fact_ten() -> None:
    assert fact(10) == 3628800
